#include <cstdint>
#include <iomanip>
#include <iostream>
#include <vector>

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    std::vector<std::uint32_t> bytes;
    for (int i = 0; i < n; ++i)
    {
        unsigned int b{};
        std::cin >> b;
        bytes.push_back(static_cast<std::uint32_t>(b & 0xFFu));
    }

    for (std::size_t i = 0; i + 3 < bytes.size(); i += 4)
    {
        std::uint32_t le{ bytes[i]
                        | (bytes[i + 1] << 8)
                        | (bytes[i + 2] << 16)
                        | (bytes[i + 3] << 24) };

        std::uint32_t be{ bytes[i + 3]
                        | (bytes[i + 2] << 8)
                        | (bytes[i + 1] << 16)
                        | (bytes[i] << 24) };

        std::cout << "le 0x" << std::hex << std::setw(8) << std::setfill('0') << le
                  << std::dec << std::setfill(' ')
                  << ' ' << le
                  << ' ' << static_cast<std::int32_t>(le) << "\n";

        std::cout << "be 0x" << std::hex << std::setw(8) << std::setfill('0') << be
                  << std::dec << std::setfill(' ')
                  << ' ' << be
                  << ' ' << static_cast<std::int32_t>(be) << "\n";
    }

    return 0;
}
